package com.bank.release.model;

// Immutable value object representing MAJOR.MINOR.PATCH.
public class SemVer {
    private final int major;
    private final int minor;
    private final int patch;

    public SemVer(int major, int minor, int patch) {
        this.major = major;
        this.minor = minor;
        this.patch = patch;
    }

    // Parse a string like "2.3.0" into a SemVer.
    public static SemVer parse(String text) {
        String clean = text.startsWith("v") ? text.substring(1) : text;
        String[] parts = clean.split("\\.");
        return new SemVer(
            Integer.parseInt(parts[0]),
            Integer.parseInt(parts[1]),
            Integer.parseInt(parts[2]));
    }

    // Breaking change: bump major, reset minor and patch.
    public SemVer bumpMajor() { return new SemVer(major + 1, 0, 0); }
    // New feature: bump minor, reset patch.
    public SemVer bumpMinor() { return new SemVer(major, minor + 1, 0); }
    // Bug fix: bump patch only.
    public SemVer bumpPatch() { return new SemVer(major, minor, patch + 1); }

    @Override
    public String toString() { return major + "." + minor + "." + patch; }
}
