package com.bank.release.model;

// A conventional commit: the type drives the version bump.
public class Commit {
    public enum Type { FIX, FEAT, BREAKING, CHORE }

    private final Type type;
    private final String message;

    public Commit(Type type, String message) {
        this.type = type;
        this.message = message;
    }

    public Type getType() { return type; }
    public String getMessage() { return message; }
}
