package com.bank.release.service;

import com.bank.release.model.Commit;
import com.bank.release.model.SemVer;
import java.util.List;
import java.util.logging.Logger;

// Reads commits since the last tag and computes the next version + changelog.
public class ReleasePlanner {
    private static final Logger log = Logger.getLogger(ReleasePlanner.class.getName());

    // Decide the next version. The HIGHEST-impact commit wins.
    public SemVer computeNextVersion(SemVer current, List<Commit> commits) {
        boolean hasBreaking = commits.stream().anyMatch(c -> c.getType() == Commit.Type.BREAKING);
        boolean hasFeature  = commits.stream().anyMatch(c -> c.getType() == Commit.Type.FEAT);
        boolean hasFix      = commits.stream().anyMatch(c -> c.getType() == Commit.Type.FIX);

        if (hasBreaking) {
            log.info("breaking change detected -> MAJOR bump");
            return current.bumpMajor();
        }
        if (hasFeature) {
            log.info("new feature detected -> MINOR bump");
            return current.bumpMinor();
        }
        if (hasFix) {
            log.info("bug fix detected -> PATCH bump");
            return current.bumpPatch();
        }
        log.info("only chores -> no release");
        return current;
    }

    // Build a human-readable changelog grouped by change type.
    public String buildChangelog(SemVer next, List<Commit> commits) {
        StringBuilder sb = new StringBuilder("## " + next + "\n\n");
        appendSection(sb, "### Breaking Changes", commits, Commit.Type.BREAKING);
        appendSection(sb, "### Features", commits, Commit.Type.FEAT);
        appendSection(sb, "### Fixes", commits, Commit.Type.FIX);
        return sb.toString();
    }

    private void appendSection(StringBuilder sb, String header,
                               List<Commit> commits, Commit.Type type) {
        List<Commit> filtered = commits.stream().filter(c -> c.getType() == type).toList();
        if (filtered.isEmpty()) return;
        sb.append(header).append("\n");
        for (Commit c : filtered) {
            sb.append("- ").append(c.getMessage()).append("\n");
        }
        sb.append("\n");
    }
}
