package com.bank.release;

import com.bank.release.model.Commit;
import com.bank.release.model.SemVer;
import com.bank.release.service.ReleasePlanner;
import java.util.List;
import java.util.logging.Logger;

public class ReleaseDemo {
    private static final Logger log = Logger.getLogger(ReleaseDemo.class.getName());

    public static void main(String[] args) {
        SemVer current = SemVer.parse("2.3.0"); // last released tag
        ReleasePlanner planner = new ReleasePlanner();

        // Commits since the last release of the Transfer Service.
        List<Commit> commits = List.of(
            new Commit(Commit.Type.FIX,  "correct rounding in interest calculation"),
            new Commit(Commit.Type.FEAT, "add UPI reference field to transfer response"),
            new Commit(Commit.Type.CHORE, "update build dependency versions")
        );

        SemVer next = planner.computeNextVersion(current, commits);
        log.info(() -> "next version: " + current + " -> " + next);
        log.info(() -> "\n" + planner.buildChangelog(next, commits));
    }
}
